#include "block_core.hpp"
#include <gmpxx.h>
namespace blockcheck {
using Int=mpz_class;
struct Counts {uint64_t d=0,a=0,n=0;};
static std::vector<int> digits(Int x,unsigned width){bool minus=x<0;if(minus)x=-x;std::vector<int> out;Int sum=0,power=1,original=x;while(x!=0){int d=0;if(mpz_odd_p(x.get_mpz_t())){Int r=x%(1u<<width);d=int(r.get_si());if(d>=(1<<(width-1)))d-=1<<width;x-=d;}sum+=power*d;power*=2;x/=2;out.push_back(minus?-d:d);}require(sum==original,"independent GMP expansion");return out;}
struct Inputs {std::vector<int> q,c;std::set<int> bank{1};Counts setup;bool minus=false;unsigned table=0;};
static Inputs inputs(const cmcache::Split&s,const cmcache::Plan&p){Inputs out;Int k(s.k.str()),c(s.c.str());out.minus=k<0;if(out.minus){k=-k;c=-c;}out.q=digits(k,p.width);out.c=digits(c,2);
 std::vector<std::tuple<int,int,bool>> chain;
 switch(p.radix){case 1:break;case 7:chain={{1,1,false},{2,2,false},{4,4,false},{8,1,true}};break;case 11:chain={{1,1,false},{2,2,false},{4,1,false},{5,5,false},{10,1,false}};break;case 13:chain={{1,1,false},{2,1,false},{3,3,false},{6,6,false},{12,1,false}};break;case 19:chain={{1,1,false},{2,2,false},{4,1,false},{5,5,false},{10,10,false},{20,1,true}};break;default:require(p.radix==2||p.radix==4||p.radix==8||p.radix==16||p.radix==32,"independent radix");for(unsigned v=1;v<p.radix;v*=2)chain.emplace_back(int(v),int(v),false);}
 auto op=[&](int a,int b,bool sub){require(out.bank.count(a)&&out.bank.count(b),"independent bank dependency");int z=sub?a-b:a+b;if(out.bank.insert(z).second){if(a==b&&!sub)++out.setup.d;else{++out.setup.a;out.setup.n+=sub;}}};for(auto [a,b,sub]:chain)op(a,b,sub);
 out.table=out.q.empty()?0:(1u<<(p.width-2));if(out.table>1){op(int(p.radix),int(p.radix),false);for(unsigned i=1;i<out.table;++i)op(int((2*i-1)*p.radix),int(2*p.radix),false);}return out;
}
static std::pair<int,int> column(const Inputs&i,const cmcache::Plan&p,size_t pos){return {pos<i.q.size()?i.q[pos]*int(p.radix):0,pos<i.c.size()?i.c[pos]:0};}
static Counts fallback(const Inputs&i,const cmcache::Plan&p){Counts out;bool started=false;for(size_t pos=std::max(i.q.size(),i.c.size());pos;--pos){if(started)++out.d;auto [a,b]=column(i,p,pos-1);std::vector<int> terms;if(a&&b&&(a+b==0||i.bank.count(std::abs(a+b)))){if(a+b)terms.push_back(a+b);}else{if(a)terms.push_back(a);if(b)terms.push_back(b);}for(int term:terms){out.n+=term<0;if(started)++out.a;else started=true;}}return out;}
static Counts program(const cmcache::Split&s,const cmcache::Plan&p,const cmblock::Program&program){auto in=inputs(s,p);require(program.table==in.table&&program.outer_sign==in.minus&&program.has_residual==!in.c.empty(),"independent prepared metadata");size_t length=std::max(in.q.size(),in.c.size()),consumed=0;Int value=0;bool started=false;Counts out;
 for(const auto&step:program.steps){require(step.bits>=1&&step.bits<=16&&consumed+step.bits<=length&&step.terms.size()<=(step.bits==1?2u:1u),"independent block program shape");Int block=0;for(unsigned j=0;j<step.bits;++j){auto [q,c]=column(in,p,length-consumed-j-1);block=2*block+q+c;}Int sum=0;for(int term:step.terms){require(term&&in.bank.count(std::abs(term)),"independent retained label");sum+=term;}require(sum==block,"independent block integer identity");value*=Int(1)<<step.bits;value+=sum;if(started)out.d+=step.bits;for(int term:step.terms){out.n+=term<0;if(started)++out.a;else started=true;}consumed+=step.bits;
 }
 Int expected=Int(p.radix)*Int(s.k.str())+Int(s.c.str());if(in.minus)expected=-expected;require(consumed==length&&value==expected,"independent complete scalar reconstruction");require(out.d==program.doubles&&out.a==program.adds&&out.n==program.negations,"independent program counts");auto old=fallback(in,p);require(out.d+out.a<=old.d+old.a,"original fallback bound");return out;
}
static bool full_counts(const cmcache::Split&s,const cmcache::Plan&p,const cmblock::Program&plan,const cmblock::Metrics&m){auto in=inputs(s,p);auto main=program(s,p,plan);auto cnt=m.bank.calls;return cnt.doubles==in.setup.d+main.d&&cnt.adds==in.setup.a+main.a&&cnt.negations==in.setup.n+main.n+uint64_t(in.minus&&!plan.steps.empty())&&cnt.table_points==uint64_t(p.radix>1)+in.table+uint64_t(!in.c.empty())&&m.bank.bank_points==in.bank.size()&&m.bank.affine_entries==(in.table>1?in.table:0);}
static auto key(const Counts&c){return std::make_tuple(c.d+c.a,c.n,c.d);}
// A separate exhaustive recursion, used only for small integer fixtures.
static Counts exhaustive(const Inputs&i,const cmcache::Plan&p,size_t pos,bool started){if(!pos)return {};bool found=false;Counts best;auto offer=[&](unsigned bits,const std::vector<int>&terms){auto tail=exhaustive(i,p,pos-bits,started||!terms.empty());if(started)tail.d+=bits;tail.a+=terms.size()-(started||terms.empty()?0:1);for(int d:terms)tail.n+=d<0;if(!found||key(tail)<key(best)){found=true;best=tail;}};auto [a,b]=column(i,p,pos-1);std::vector<int> terms;if(a&&b&&(a+b==0||i.bank.count(std::abs(a+b)))){if(a+b)terms.push_back(a+b);}else{if(a)terms.push_back(a);if(b)terms.push_back(b);}offer(1,terms);Int value=0;for(unsigned bits=1;bits<=16&&bits<=pos;++bits){auto [q,c]=column(i,p,pos-bits);value=2*value+q+c;if(bits>1&&(value==0||(mpz_fits_sint_p(value.get_mpz_t())&&i.bank.count(std::abs(int(value.get_si())))))){std::vector<int> term;if(value!=0)term.push_back(int(value.get_si()));offer(bits,term);}}return best;}
}
int main(int argc,char**argv){try{require(argc==2,"block-qual FIXTURES");uint64_t integer_checks=0,exhaustive_checks=0,point_checks=0,bank_checks=0,negative=0,leading=0,folded=0;
 for(unsigned radix:{1u,7u,11u,13u,19u})for(unsigned width:{2u,4u})for(long k:{-8L,-1L,0L,1L,2L,8L})for(long c:{-8L,-1L,0L,1L,8L}){cmcache::Plan p{radix,width,0,0};cmcache::Split split{Big(k),Big(c)};auto plan=cmblock::prepare(split,p);auto counts=blockcheck::program(split,p,plan);auto in=blockcheck::inputs(split,p);require(blockcheck::key(counts)==blockcheck::key(blockcheck::exhaustive(in,p,std::max(in.q.size(),in.c.size()),false)),"independent exhaustive block minimum");++integer_checks;++exhaustive_checks;for(const auto&step:plan.steps)folded+=step.bits>1;if(!plan.steps.empty())leading+=plan.steps[0].bits>1;if(!plan.steps.empty()&&!plan.steps[0].terms.empty()){auto bad=plan;bad.steps[0].terms[0]+=1;bool rejected=false;try{blockcheck::program(split,p,bad);}catch(const std::exception&){rejected=true;}require(rejected,"changed block control");++negative;}}
 require(folded&&leading,"planted folding and leading controls exercised");
 for(auto&f:fixtures(argv[1])){Runtime r(f,true);verify_relation(r);for(long input:{0L,1L,17L,-1L}){Big scalar(input),residue;require(BN_nnmod(residue.p,scalar.p,r.n.p,r.field.ctx),"block input residue");auto P=point(r.group),out=point(r.group),expected=point(r.group);require(EC_POINT_mul(r.group,P.get(),residue.p,nullptr,nullptr,r.field.ctx)&&EC_POINT_mul(r.group,expected.get(),nullptr,P.get(),r.mu.p,r.field.ctx),"block reference");
  auto audit=[&](int coefficient,const EC_POINT*value){Big k(coefficient);auto check=point(r.group);require(EC_POINT_mul(r.group,check.get(),nullptr,P.get(),k.p,r.field.ctx)&&EC_POINT_cmp(r.group,check.get(),value,r.field.ctx)==0,"independent folded bank point");++bank_checks;};
  if(input==1){auto p=cmcache::deterministic(f);auto split=cmcache::decompose(r,p);cmcache::Metrics original;cmcache::multiply(r,out.get(),P.get(),split,p,true,original);require(EC_POINT_cmp(r.group,out.get(),expected.get(),r.field.ctx)==0,"original fallback point control");}
  for(unsigned radix:{1u,2u,4u,8u,16u,32u,unsigned(f.marked.at("degree").integer())})for(unsigned width=2;width<=7;++width)for(int offset:{-64,0,64}){cmcache::Plan p{radix,width,offset,0};auto split=cmcache::decompose(r,p);auto plan=cmblock::prepare(split,p);blockcheck::program(split,p,plan);++integer_checks;cmblock::Metrics m;cmblock::multiply(r,out.get(),P.get(),split,p,m,audit);require(EC_POINT_cmp(r.group,out.get(),expected.get(),r.field.ctx)==0,"folded original mu output");if(input)require(blockcheck::full_counts(split,p,plan,m),"independent complete block counts");else require(m.bank.calls.doubles==0&&m.bank.calls.adds==0&&m.bank.bank_points==0,"identity setup skipped");++point_checks;
  }
 }}
 std::cout<<"{\"independent_GMP_program_checks\":"<<integer_checks<<",\"exhaustive_small_program_minima\":"<<exhaustive_checks<<",\"original_mu_point_checks\":"<<point_checks<<",\"independent_bank_labels\":"<<bank_checks<<",\"altered_program_rejections\":"<<negative<<",\"planted_multicolumn_controls\":"<<folded<<",\"planted_leading_controls\":"<<leading<<",\"timing_performed\":false}\n";return 0;
}catch(const std::exception&e){std::cerr<<"block qualification failed: "<<e.what()<<'\n';return 1;}}
